package com.reo.darkshift

import android.content.Context
import android.content.SharedPreferences

/** Slider values are all 0..1, same as the GNOME extension. */
data class DarkshiftConfig(
    val enabled: Boolean = DEFAULT_ENABLED,
    val monotone: Boolean = DEFAULT_MONOTONE,
    val darkness: Float = DEFAULT_DARKNESS,
    /** 0 = green, 1 = red. */
    val colorShift: Float = DEFAULT_COLOR_SHIFT,
    val maxValue: Float = DEFAULT_MAX_VALUE,
) {
    companion object {
        const val DEFAULT_ENABLED = false
        const val DEFAULT_MONOTONE = false
        const val DEFAULT_DARKNESS = 0.5f
        const val DEFAULT_COLOR_SHIFT = 1f / 3f
        const val DEFAULT_MAX_VALUE = 1f
    }
}

class DarkshiftSettings(context: Context) {
    private val prefs: SharedPreferences =
        context.applicationContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)

    var config: DarkshiftConfig
        get() = DarkshiftConfig(
            enabled = prefs.getBoolean(KEY_ENABLED, DarkshiftConfig.DEFAULT_ENABLED),
            monotone = prefs.getBoolean(KEY_MONOTONE, DarkshiftConfig.DEFAULT_MONOTONE),
            darkness = prefs.getFloat(KEY_DARKNESS, DarkshiftConfig.DEFAULT_DARKNESS),
            colorShift = prefs.getFloat(KEY_COLOR_SHIFT, DarkshiftConfig.DEFAULT_COLOR_SHIFT),
            maxValue = prefs.getFloat(KEY_MAX_VALUE, DarkshiftConfig.DEFAULT_MAX_VALUE),
        )
        set(value) = prefs.edit()
            .putBoolean(KEY_ENABLED, value.enabled)
            .putBoolean(KEY_MONOTONE, value.monotone)
            .putFloat(KEY_DARKNESS, value.darkness)
            .putFloat(KEY_COLOR_SHIFT, value.colorShift)
            .putFloat(KEY_MAX_VALUE, value.maxValue)
            .apply()

    fun update(change: (DarkshiftConfig) -> DarkshiftConfig) {
        config = change(config)
    }

    /** Back to the default slider values; the on/off state is left alone. */
    fun reset() = update { DarkshiftConfig(enabled = it.enabled) }

    fun registerListener(listener: SharedPreferences.OnSharedPreferenceChangeListener) =
        prefs.registerOnSharedPreferenceChangeListener(listener)

    fun unregisterListener(listener: SharedPreferences.OnSharedPreferenceChangeListener) =
        prefs.unregisterOnSharedPreferenceChangeListener(listener)

    private companion object {
        const val PREFS_NAME = "darkshift"
        const val KEY_ENABLED = "enabled"
        const val KEY_MONOTONE = "monotone"
        const val KEY_DARKNESS = "darkness"
        const val KEY_COLOR_SHIFT = "colorShift"
        const val KEY_MAX_VALUE = "maxValue"
    }
}

package com.reo.darkshift

import kotlin.math.roundToInt

/**
 * Turns the slider values into the one translucent color the overlay is filled with.
 *
 * An overlay can only alpha-blend over the screen (out = screen * (1 - a) + color * a), so unlike
 * the GNOME shader it cannot treat pixels individually. What it can do exactly:
 *  - scale every pixel's brightness (Max value and Darkness), by blending in black;
 *  - tint the picture towards green or red (Green <-> Red), by blending in a little of that color.
 *    That tint also lifts true black slightly, so it is kept weak.
 */
object OverlayColor {
    /** Max value scales the brightest channel from this share up to 1. */
    const val MIN_MAX_VALUE = 0.33f

    /** Darkness at 1 dims the screen by this share, on top of Max value. */
    const val MAX_DARKNESS_DIM = 0.4f

    const val TINT_ALPHA = 0.08f
    const val MONOTONE_TINT_ALPHA = 0.16f

    /** Share of the original brightness that stays visible. */
    fun brightness(config: DarkshiftConfig): Float =
        mix(MIN_MAX_VALUE, 1f, config.maxValue.coerceIn(0f, 1f)) *
            (1f - config.darkness.coerceIn(0f, 1f) * MAX_DARKNESS_DIM)

    /** Straight (non-premultiplied) ARGB for the overlay view's background. */
    fun argb(config: DarkshiftConfig): Int {
        val shift = config.colorShift.coerceIn(0f, 1f).let {
            if (config.monotone) (if (it >= 0.5f) 1f else 0f) else it
        }
        val tintAlpha = if (config.monotone) MONOTONE_TINT_ALPHA else TINT_ALPHA
        val dim = 1f - brightness(config)

        // Tint first, then dim: out = screen * (1 - tint) * (1 - dim) + tintColor * tint * (1 - dim).
        val alpha = 1f - (1f - tintAlpha) * (1f - dim)
        if (alpha <= 0f) return 0
        val red = (shift * 2f).coerceAtMost(1f)
        val green = ((1f - shift) * 2f).coerceAtMost(1f)
        val scale = tintAlpha * (1f - dim) / alpha

        return (alpha.toByte255() shl 24) or
            ((red * scale).toByte255() shl 16) or
            ((green * scale).toByte255() shl 8)
    }

    private fun mix(a: Float, b: Float, t: Float) = a + (b - a) * t

    private fun Float.toByte255() = (this * 255f).roundToInt().coerceIn(0, 255)
}

package com.reo.darkshift

import android.accessibilityservice.AccessibilityService
import android.content.ComponentName
import android.content.Intent
import android.content.SharedPreferences
import android.graphics.PixelFormat
import android.service.quicksettings.TileService
import android.view.View
import android.view.WindowManager
import android.view.accessibility.AccessibilityEvent

/** Draws the full-screen dimming/tint overlay. It only needs to exist to be allowed to add one. */
class DarkshiftService : AccessibilityService(), SharedPreferences.OnSharedPreferenceChangeListener {
    private lateinit var settings: DarkshiftSettings
    private var overlay: View? = null

    override fun onServiceConnected() {
        settings = DarkshiftSettings(this)
        settings.registerListener(this)
        isRunning = true
        refresh()
        requestTileRefresh()
    }

    override fun onSharedPreferenceChanged(prefs: SharedPreferences?, key: String?) = refresh()

    private fun refresh() {
        val config = settings.config
        if (!config.enabled) {
            removeOverlay()
            return
        }
        val view = overlay ?: addOverlay()
        view.setBackgroundColor(OverlayColor.argb(config))
    }

    private fun addOverlay(): View {
        val view = View(this)
        val params = WindowManager.LayoutParams(
            WindowManager.LayoutParams.MATCH_PARENT,
            WindowManager.LayoutParams.MATCH_PARENT,
            WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE or
                WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN or
                WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,
            PixelFormat.TRANSLUCENT,
        ).apply {
            layoutInDisplayCutoutMode = WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_ALWAYS
            fitInsetsTypes = 0
            title = "Darkshift"
        }
        getSystemService(WindowManager::class.java).addView(view, params)
        overlay = view
        return view
    }

    private fun removeOverlay() {
        val view = overlay ?: return
        overlay = null
        getSystemService(WindowManager::class.java).removeView(view)
    }

    private fun requestTileRefresh() =
        TileService.requestListeningState(this, ComponentName(this, DarkshiftTileService::class.java))

    override fun onUnbind(intent: Intent?): Boolean {
        shutDown()
        return super.onUnbind(intent)
    }

    override fun onDestroy() {
        shutDown()
        super.onDestroy()
    }

    private fun shutDown() {
        if (!isRunning) return
        isRunning = false
        settings.unregisterListener(this)
        removeOverlay()
        requestTileRefresh()
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent?) = Unit

    override fun onInterrupt() = Unit

    companion object {
        /** True while the user has the accessibility service switched on. */
        @Volatile
        var isRunning = false
            private set
    }
}

package com.reo.darkshift

import android.app.PendingIntent
import android.content.Intent
import android.service.quicksettings.Tile
import android.service.quicksettings.TileService

class DarkshiftTileService : TileService() {
    override fun onStartListening() = refresh()

    override fun onClick() {
        if (!DarkshiftService.isRunning) {
            // Nothing to toggle until the accessibility service is on; the app explains how.
            val intent = Intent(this, MainActivity::class.java)
            startActivityAndCollapse(PendingIntent.getActivity(this, 0, intent, PendingIntent.FLAG_IMMUTABLE))
            return
        }
        DarkshiftSettings(this).update { it.copy(enabled = !it.enabled) }
        refresh()
    }

    private fun refresh() {
        val tile = qsTile ?: return
        val on = DarkshiftService.isRunning && DarkshiftSettings(this).config.enabled
        tile.state = if (on) Tile.STATE_ACTIVE else Tile.STATE_INACTIVE
        tile.subtitle = getString(
            when {
                !DarkshiftService.isRunning -> R.string.tile_needs_service
                on -> R.string.tile_on
                else -> R.string.tile_off
            }
        )
        tile.updateTile()
    }
}

package com.reo.darkshift

import android.content.Intent
import android.os.Bundle
import android.provider.Settings
import android.view.View
import android.widget.Button
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import com.google.android.material.button.MaterialButtonToggleGroup
import com.google.android.material.materialswitch.MaterialSwitch
import com.google.android.material.slider.Slider
import kotlin.math.roundToInt

class MainActivity : AppCompatActivity() {
    private lateinit var settings: DarkshiftSettings

    private lateinit var serviceCard: View
    private lateinit var enableSwitch: MaterialSwitch
    private lateinit var modeGroup: MaterialButtonToggleGroup
    private lateinit var darknessSlider: Slider
    private lateinit var colorShiftRow: View
    private lateinit var colorShiftSlider: Slider
    private lateinit var colorChoiceGroup: MaterialButtonToggleGroup
    private lateinit var maxValueSlider: Slider
    private lateinit var maxValueLabel: TextView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)
        settings = DarkshiftSettings(this)

        serviceCard = findViewById(R.id.service_card)
        enableSwitch = findViewById(R.id.enable_switch)
        modeGroup = findViewById(R.id.mode_group)
        darknessSlider = findViewById(R.id.darkness_slider)
        colorShiftRow = findViewById(R.id.color_shift_row)
        colorShiftSlider = findViewById(R.id.color_shift_slider)
        colorChoiceGroup = findViewById(R.id.color_choice_group)
        maxValueSlider = findViewById(R.id.max_value_slider)
        maxValueLabel = findViewById(R.id.max_value_label)

        findViewById<Button>(R.id.open_accessibility_settings).setOnClickListener {
            startActivity(Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))
        }

        enableSwitch.setOnCheckedChangeListener { button, checked ->
            if (button.isPressed) settings.update { it.copy(enabled = checked) }
        }
        modeGroup.addOnButtonCheckedListener { _, id, checked ->
            if (!checked) return@addOnButtonCheckedListener
            settings.update { it.copy(monotone = id == R.id.mode_monotone) }
            render()
        }
        colorChoiceGroup.addOnButtonCheckedListener { _, id, checked ->
            if (!checked) return@addOnButtonCheckedListener
            settings.update { it.copy(colorShift = if (id == R.id.choice_red) 1f else 0f) }
        }
        darknessSlider.addOnChangeListener { _, value, fromUser ->
            if (fromUser) settings.update { it.copy(darkness = value) }
        }
        colorShiftSlider.addOnChangeListener { _, value, fromUser ->
            if (fromUser) settings.update { it.copy(colorShift = value) }
        }
        maxValueSlider.addOnChangeListener { _, value, fromUser ->
            maxValueLabel.text = maxValuePercent(value)
            if (fromUser) settings.update { it.copy(maxValue = value) }
        }
        findViewById<Button>(R.id.reset_button).setOnClickListener {
            settings.reset()
            render()
        }
    }

    override fun onResume() {
        super.onResume()
        render()
    }

    /** Shows what is saved; the listeners above only write back changes made by the user. */
    private fun render() {
        val config = settings.config
        serviceCard.visibility = if (DarkshiftService.isRunning) View.GONE else View.VISIBLE
        enableSwitch.isChecked = config.enabled
        modeGroup.check(if (config.monotone) R.id.mode_monotone else R.id.mode_multicolor)
        darknessSlider.value = config.darkness.coerceIn(0f, 1f)
        colorShiftSlider.value = config.colorShift.coerceIn(0f, 1f)
        maxValueSlider.value = config.maxValue.coerceIn(0f, 1f)
        maxValueLabel.text = maxValuePercent(config.maxValue)

        // Monotone mode has no in-between: just pick green or red.
        colorShiftRow.visibility = if (config.monotone) View.GONE else View.VISIBLE
        colorChoiceGroup.visibility = if (config.monotone) View.VISIBLE else View.GONE
        colorChoiceGroup.check(if (config.colorShift >= 0.5f) R.id.choice_red else R.id.choice_green)
    }

    private fun maxValuePercent(value: Float): String {
        val brightness = OverlayColor.MIN_MAX_VALUE + (1f - OverlayColor.MIN_MAX_VALUE) * value
        return "${(brightness * 100).roundToInt()}%"
    }
}

